import {
  AssessmentRounded,
  LogoutRounded,
  TimelineRounded,
  MemoryRounded,
  MonitorHeartRounded,
  BoltRounded,
} from "@mui/icons-material";

import {
  Box,
  List,
  ListItemButton,
  ListItemIcon,
  ListItemText,
  Typography,
  Divider,
  Chip,
} from "@mui/material";

import { NavLink } from "react-router-dom";
import { ROUTES } from "../../routes/routes";
import logo from "../../assets/Eskom-logo-white.gif";

const navigation = [
  {
    title: "FORECAST",
    icon: TimelineRounded,
    path: ROUTES.FORECAST,
    status: "LIVE",
  },
  {
    title: "PERFORMANCE",
    icon: AssessmentRounded,
    path: ROUTES.MODEL_PERFORMANCE,
    status: null,
  },
  {
    title: "SYSTEM HEALTH",
    icon: MemoryRounded,
    path: ROUTES.INFERENCE,
    status: null,
  },
  {
    title: "ACTIVITY",
    icon: MonitorHeartRounded,
    path: ROUTES.INFERENCE_MONITORING,
    status: "NEW",
  },
];

const DashboardSidebar = () => {
  return (
    <Box
      sx={{
        width: 280,
        height: "100vh",
        background: "#000000",
        color: "#fff",
        display: "flex",
        flexDirection: "column",
        borderRight: "4px solid #E2231A",
        boxShadow: "4px 0 20px rgba(226, 35, 26, 0.3)",
        position: "relative",
        overflow: "hidden",
      }}
    >
      {/* Eskom Red accent gradient */}
      <Box
        sx={{
          position: "absolute",
          top: 0,
          left: 0,
          right: 0,
          height: "200px",
          background: "linear-gradient(180deg, rgba(226, 35, 26, 0.15) 0%, transparent 100%)",
          pointerEvents: "none",
        }}
      />

      {/* Logo & Branding */}
      <Box
        sx={{
          px: 3,
          py: 4,
          position: "relative",
          zIndex: 1,
          borderBottom: "2px solid rgba(226, 35, 26, 0.3)",
        }}
      >
        <Box
          component="img"
          src={logo}
          alt="Eskom"
          sx={{
            width: 140,
            mb: 2,
            filter: "drop-shadow(0 4px 8px rgba(226, 35, 26, 0.5))",
          }}
        />
        <Typography
          sx={{
            fontSize: "0.6875rem",
            color: "#E2231A",
            fontWeight: 900,
            letterSpacing: "0.15em",
            textTransform: "uppercase",
          }}
        >
          FORECAST CONTROL
        </Typography>
        <Typography
          sx={{
            fontSize: "0.625rem",
            color: "rgba(255, 255, 255, 0.5)",
            fontWeight: 600,
            letterSpacing: "0.05em",
            mt: 0.5,
          }}
        >
          Advanced Analytics Platform
        </Typography>
      </Box>

      {/* Navigation */}
      <List
        sx={{
          px: 2,
          flex: 1,
          position: "relative",
          zIndex: 1,
          pt: 3,
        }}
      >
        {navigation.map((item) => {
          const Icon = item.icon;
          return (
            <ListItemButton
              key={item.path}
              component={NavLink}
              to={item.path}
              sx={{
                borderRadius: 1,
                mb: 1,
                py: 2,
                px: 2,
                border: "1px solid transparent",
                transition: "all 0.2s cubic-bezier(0.4, 0, 0.2, 1)",

                "&:hover": {
                  backgroundColor: "rgba(226, 35, 26, 0.1)",
                  border: "1px solid rgba(226, 35, 26, 0.3)",
                  transform: "translateX(4px)",
                },

                "&.active": {
                  backgroundColor: "#E2231A",
                  border: "1px solid #E2231A",
                  boxShadow: "0 4px 12px rgba(226, 35, 26, 0.5)",
                  transform: "translateX(4px)",

                  "&::before": {
                    content: '""',
                    position: "absolute",
                    left: 0,
                    top: 0,
                    bottom: 0,
                    width: "4px",
                    background: "#FFFFFF",
                  },
                },
              }}
            >
              <ListItemIcon
                sx={{
                  color: "inherit",
                  minWidth: 40,
                  "& .MuiSvgIcon-root": {
                    fontSize: "1.5rem",
                  },
                }}
              >
                <Icon />
              </ListItemIcon>

              <ListItemText
                primary={item.title}
                primaryTypographyProps={{
                  fontWeight: 800,
                  fontSize: "0.8125rem",
                  letterSpacing: "0.05em",
                }}
              />

              {item.status && (
                <Chip
                  label={item.status}
                  size="small"
                  sx={{
                    height: 20,
                    fontSize: "0.625rem",
                    fontWeight: 800,
                    background: item.status === "LIVE" ? "#00C853" : "#FFD600",
                    color: item.status === "LIVE" ? "#000" : "#000",
                    border: "none",
                    letterSpacing: "0.05em",
                  }}
                />
              )}
            </ListItemButton>
          );
        })}
      </List>

      {/* System Status */}
      <Box
        sx={{
          px: 2,
          pb: 2,
          position: "relative",
          zIndex: 1,
        }}
      >
        <Box
          sx={{
            background: "rgba(0, 200, 83, 0.15)",
            border: "2px solid #00C853",
            borderRadius: 1,
            p: 2,
            mb: 2,
          }}
        >
          <Box display="flex" alignItems="center" gap={1} mb={1}>
            <BoltRounded sx={{ color: "#00C853", fontSize: "1.25rem" }} />
            <Typography
              sx={{
                fontSize: "0.75rem",
                fontWeight: 800,
                color: "#00C853",
                letterSpacing: "0.05em",
                textTransform: "uppercase",
              }}
            >
              OPERATIONAL
            </Typography>
          </Box>
          <Typography
            sx={{
              fontSize: "0.625rem",
              color: "rgba(255, 255, 255, 0.6)",
              fontWeight: 600,
            }}
          >
            All systems running
          </Typography>
        </Box>
      </Box>

      {/* Footer */}
      <Box
        sx={{
          p: 2,
          pt: 0,
          position: "relative",
          zIndex: 1,
        }}
      >
        <Divider sx={{ borderColor: "rgba(226, 35, 26, 0.3)", borderWidth: 1, mb: 2 }} />
        <ListItemButton
          sx={{
            borderRadius: 1,
            py: 1.5,
            background: "rgba(226, 35, 26, 0.15)",
            border: "1px solid rgba(226, 35, 26, 0.3)",

            "&:hover": {
              background: "rgba(226, 35, 26, 0.25)",
              border: "1px solid rgba(226, 35, 26, 0.5)",
            },
          }}
        >
          <ListItemIcon sx={{ color: "#E2231A", minWidth: 40 }}>
            <LogoutRounded />
          </ListItemIcon>
          <ListItemText
            primary="LOGOUT"
            primaryTypographyProps={{
              fontWeight: 800,
              color: "#E2231A",
              fontSize: "0.8125rem",
              letterSpacing: "0.05em",
            }}
          />
        </ListItemButton>
      </Box>
    </Box>
  );
};

export default DashboardSidebar;
